{$ param month label="Month Abbrev" default="APR" description="Three-letter month shown in the date badge." $}
{$ param day label="Day" default="10" description="Day number in the date badge." $}
{$ param time label="Time" default="7pm EST" description="Time displayed under the date." $}
{$ param tag label="Tag" default="Zoom" description="Location or format tag." $}
{$ param image_url label="Image URL" default="" description="Optional event image." type="fileurl" $}
{$ param image_alt label="Image Alt" default="" description="Accessibility description." $}
{$ param title label="Event Title" default="Event Name" description="Event heading." $}
{$ param date_line label="Date Line" default="April 10, 2026 · 7pm to 9pm EST" description="Human-readable date/time line." $}
{$ param location_line label="Location Line" default="Zoom link or venue address" description="Where the event happens." $}
{$ param register_href label="Register URL" default="#" description="Registration link." $}
{$ param register_label label="Register Label" default="Register" description="Register button text." $}
{$ param details_href label="Details URL" default="#" description="Event details link." $}
{$ param details_label label="Details Label" default="Find Out More" description="Details button text." $}

<div class="ss-ec ss-ec-upcoming mb-4">
  <div class="ss-ec-info">
    <div><span class="cc-ec-info-month">{$= month $}</span> <span class="cc-ec-info-day">{$= day $}</span></div>
    <div class="cc-ec-info-time">{$= time $}</div>
    <div class="ss-ec-tag"><span>{$= tag $}</span></div>
  </div>
  <div class="ss-ec-content">
    {$ if image_url $}<img src="{$= image_url $}" alt="{$= image_alt $}" />{$ /if $}
    <h3><a href="{$= details_href $}">{$= title $}</a></h3>
    <h4>{$= date_line $}</h4>
    <div class="ss-ec-loc">{$= location_line $}</div>
    {$ slot description $}
      <p>Event description.</p>
    {$ /slot $}
    <a href="{$= register_href $}" class="btn btn-primary">{$= register_label $}</a>
    <a href="{$= details_href $}" class="btn btn-secondary">{$= details_label $}</a>
  </div>
</div>
